'use strict';
// ID formats - Data Dictionary section 7 / section 8 (prefix + zero-padded sequence).
// IDs are always generated by the server; never accepted from the client.

const ID_FORMATS = Object.freeze({
  EMPLOYEE: { table: 'EMPLOYEE', column: 'employee_id', prefix: 'EMP', digits: 5 },
  ATTENDANCE: { table: 'ATTENDANCE', column: 'attendance_id', prefix: 'ATT', digits: 9 },
  LEAVE_APPLICATION: { table: 'LEAVE_APPLICATION', column: 'leave_id', prefix: 'LV', digits: 8 },
  VACANCY: { table: 'VACANCY', column: 'vacancy_id', prefix: 'VAC', digits: 5 },
  CANDIDATE: { table: 'CANDIDATE', column: 'candidate_id', prefix: 'CAN', digits: 5 },
  INTERVIEW_SCHEDULE: { table: 'INTERVIEW_SCHEDULE', column: 'interview_id', prefix: 'INT', digits: 7 },
  OFFER: { table: 'OFFER', column: 'offer_id', prefix: 'OFR', digits: 7 },
  PAYROLL: { table: 'PAYROLL', column: 'payroll_id', prefix: 'PAY', digits: 9 },
  PAYSLIP: { table: 'PAYSLIP', column: 'payslip_id', prefix: 'PS', digits: 10 },
  RETIREMENT_PLAN: { table: 'RETIREMENT_PLAN', column: 'ret_plan_id', prefix: 'RP', digits: 6 },
});

function formatId(kind, seq) {
  const f = ID_FORMATS[kind];
  if (!f) throw new Error(`Unknown ID kind ${kind}`);
  const s = String(seq);
  if (!Number.isInteger(seq) || seq < 1 || s.length > f.digits) {
    throw new Error(`${kind} sequence out of range: ${seq}`);
  }
  return f.prefix + s.padStart(f.digits, '0');
}

/** Regex that matches a valid ID of the given kind, e.g. /^EMP\d{5}$/. */
function idPattern(kind) {
  const f = ID_FORMATS[kind];
  return new RegExp(`^${f.prefix}\\d{${f.digits}}$`);
}

/**
 * Next ID for a table. Must be called inside the same transaction as the INSERT
 * (better-sqlite3 is synchronous, so the read and insert cannot interleave).
 */
function nextId(db, kind) {
  const f = ID_FORMATS[kind];
  if (!f) throw new Error(`Unknown ID kind ${kind}`);
  const start = f.prefix.length + 1;
  const row = db
    .prepare(
      `SELECT MAX(CAST(substr(${f.column}, ${start}) AS INTEGER)) AS max_seq
         FROM ${f.table} WHERE ${f.column} LIKE ?`
    )
    .get(`${f.prefix}%`);
  return formatId(kind, (row.max_seq || 0) + 1);
}

module.exports = { ID_FORMATS, formatId, idPattern, nextId };
